1	package mevwatch
2	
3	import (
4		"bufio"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"syscall"
14	)
15	
16	// Block is one validated, deduplicated input block. Swaps are kept in
17	// canonical order: exact duplicates removed, sorted by Index.
18	type Block struct {
19		ChainID     string
20		BlockHash   string
21		BlockNumber int64
22		Swaps       []Swap
23	}
24	
25	// ReportFinding is one risk conclusion inside a block report. Evidence
26	// carries the raw fields of every swap that participated in the judgment.
27	type ReportFinding struct {
28		Kind     string `json:"kind"`
29		Severity int    `json:"severity"`
30		TxHash   string `json:"txHash"`
31		Evidence []Swap `json:"evidence"`
32	}
33	
34	// Report is the archived per-block risk report. Version records the full
35	// rule parameters that produced the findings, so the report stays
36	// interpretable without the original rule definition.
37	type Report struct {
38		ChainID     string          `json:"chainId"`
39		BlockHash   string          `json:"blockHash"`
40		BlockNumber int64           `json:"blockNumber"`
41		SwapCount   int             `json:"swapCount"`
42		Version     RuleVersion     `json:"version"`
43		Findings    []ReportFinding `json:"findings"`
44	}
45	
46	// LineError pins a replay failure to a 1-based input line.
47	type LineError struct {
48		Line int
49		Err  error
50	}
51	
52	func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
53	func (e *LineError) Unwrap() error { return e.Err }
54	
55	// ErrBusy reports an archive locked by another process.
56	var ErrBusy = errors.New("archive is busy")
57	
58	// ErrUnknownBlock reports a query for a block that was never archived.
59	var ErrUnknownBlock = errors.New("unknown block")
60	
61	type blockID struct {
62		chainID   string
63		blockHash string
64	}
65	
66	// swapLine mirrors one swap record inside a block line. Pointers
67	// distinguish a missing field (or an explicit null) from an explicit
68	// zero value: a replay record must be complete on its own, so In, Out,
69	// GasPrice and Index are all required and may not be null.
70	type swapLine struct {
71		TxHash   *string `json:"TxHash"`
72		Pool     *string `json:"Pool"`
73		Trader   *string `json:"Trader"`
74		In       *int64  `json:"In"`
75		Out      *int64  `json:"Out"`
76		GasPrice *int64  `json:"GasPrice"`
77		Index    *int    `json:"Index"`
78	}
79	
80	// blockLine mirrors one input line. Pointers distinguish a missing field
81	// from an explicit zero value.
82	type blockLine struct {
83		ChainID     *string     `json:"chainId"`
84		BlockHash   *string     `json:"blockHash"`
85		BlockNumber *int64      `json:"blockNumber"`
86		Swaps       *[]swapLine `json:"swaps"`
87	}
88	
89	func parseBlock(text string) (Block, error) {
90		var raw blockLine
91		dec := json.NewDecoder(strings.NewReader(text))
92		if err := dec.Decode(&raw); err != nil {
93			return Block{}, fmt.Errorf("invalid JSON: %w", err)
94		}
95		if err := blockTrailingData(text, int(dec.InputOffset())); err != nil {
96			return Block{}, err
97		}
98		if raw.ChainID == nil || *raw.ChainID == "" {
99			return Block{}, errors.New("chainId must be a non-empty string")
100		}
101		if raw.BlockHash == nil || *raw.BlockHash == "" {
102			return Block{}, errors.New("blockHash must be a non-empty string")
103		}
104		if raw.BlockNumber == nil {
105			return Block{}, errors.New("blockNumber is required")
106		}
107		if *raw.BlockNumber < 0 {
108			return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
109		}
110		if raw.Swaps == nil {
111			return Block{}, errors.New("swaps must be an array")
112		}
113	
114		byTx := make(map[string]Swap)
115		byIndex := make(map[int]string)
116		swaps := []Swap{}
117		for i, s := range *raw.Swaps {
118			if s.TxHash == nil || *s.TxHash == "" {
119				return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
120			}
121			if s.Pool == nil || *s.Pool == "" {
122				return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
123			}
124			if s.Trader == nil || *s.Trader == "" {
125				return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
126			}
127			// Every numeric field must be present and non-null in this very
128			// record; an explicit zero is a valid value, never a missing one.
129			// Values must not be borrowed from a neighbour, a same-hash record
130			// or a default, so an incomplete record is rejected before dedup
131			// even when a complete record with the same tx hash exists.
132			for _, f := range []struct {
133				name string
134				v    *int64
135			}{
136				{"In", s.In}, {"Out", s.Out}, {"GasPrice", s.GasPrice},
137			} {
138				if f.v == nil {
139					return Block{}, fmt.Errorf("swaps[%d]: %s is required and must not be null", i, f.name)
140				}
141			}
142			if s.Index == nil {
143				return Block{}, fmt.Errorf("swaps[%d]: Index is required and must not be null", i)
144			}
145			in, out, gasPrice, index := *s.In, *s.Out, *s.GasPrice, *s.Index
146			if in < 0 || out < 0 || gasPrice < 0 || index < 0 {
147				return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
148			}
149			swap := Swap{
150				TxHash: *s.TxHash, Pool: *s.Pool, Trader: *s.Trader,
151				In: in, Out: out, GasPrice: gasPrice, Index: index,
152			}
153			if prev, ok := byTx[swap.TxHash]; ok {
154				if prev != swap {
155					return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, swap.TxHash)
156				}
157				continue // exact duplicate, keep one copy
158			}
159			if other, ok := byIndex[swap.Index]; ok {
160				return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, swap.Index, other)
161			}
162			byTx[swap.TxHash] = swap
163			byIndex[swap.Index] = swap.TxHash
164			swaps = append(swaps, swap)
165		}
166		sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
167		return Block{
168			ChainID:     *raw.ChainID,
169			BlockHash:   *raw.BlockHash,
170			BlockNumber: *raw.BlockNumber,
171			Swaps:       swaps,
172		}, nil
173	}
174	
175	// blockTrailingData names the first non-whitespace byte after the block
176	// object on a replay line, so an unmatched '}' or ']' — or a second value
177	// of any kind — is reported directly; only whitespace may follow the
178	// object. dec.More cannot see this: after a complete top-level value it
179	// only looks for the start of another value and treats stray closing
180	// brackets as "nothing more".
181	func blockTrailingData(text string, offset int) error {
182		rest := strings.TrimLeft(text[offset:], " \t\n\r")
183		if len(rest) > 0 {
184			return fmt.Errorf("invalid JSON: unexpected trailing data after block object: %s", trailingTokenName(rest[0]))
185		}
186		return nil
187	}
188	
189	func swapsEqual(a, b []Swap) bool {
190		if len(a) != len(b) {
191			return false
192		}
193		for i := range a {
194			if a[i] != b[i] {
195				return false
196			}
197		}
198		return true
199	}
200	
201	// sameContent reports whether two blocks carry the same content. Both sides
202	// are canonical (deduplicated, sorted by Index), so ordering and exact
203	// duplicates in the input do not affect the comparison.
204	func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
205		return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
206	}
207	
208	// DetectBlock checks every swap against its adjacent neighbours within its
209	// pool under the built-in rules. See DetectBlockWithRules.
210	func DetectBlock(swaps []Swap) []ReportFinding {
211		return DetectBlockWithRules(swaps, BuiltinVersion().Rules)
212	}
213	
214	// DetectBlockWithRules checks every swap against its adjacent neighbours
215	// within its pool under the given rule version: a sandwich when the same
216	// trader brackets the victim with higher gas on both sides, otherwise a
217	// displacement when the previous swap's gas strictly exceeds the configured
218	// multiple of the victim's. The last swap of a pool is checked too. An
219	// enabled sandwich takes priority over displacement for the same victim;
220	// with the sandwich rule off the victim can still be flagged for
221	// displacement. With both rules off the result is an empty slice. The
222	// judgment itself is shared with Detect; this entry only adds the block
223	// report's raw-swap evidence and ordering.
224	func DetectBlockWithRules(swaps []Swap, rules RuleSet) []ReportFinding {
225		pools := make(map[string][]Swap)
226		for _, s := range swaps {
227			pools[s.Pool] = append(pools[s.Pool], s)
228		}
229		findings := []ReportFinding{}
230		for _, pool := range pools {
231			sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
232			for i, victim := range pool {
233				var front, back *Swap
234				if i > 0 {
235					front = &pool[i-1]
236				}
237				if i+1 < len(pool) {
238					back = &pool[i+1]
239				}
240				j, hit := judgeVictim(front, victim, back, rules)
241				if !hit {
242					continue
243				}
244				// The evidence keeps the full swap fields of every record that
245				// participated: front, victim, and for a sandwich also back.
246				evidence := []Swap{*front, victim}
247				if j.kind == "sandwich" {
248					evidence = append(evidence, *back)
249				}
250				findings = append(findings, ReportFinding{
251					Kind: j.kind, Severity: j.severity, TxHash: victim.TxHash,
252					Evidence: evidence,
253				})
254			}
255		}
256		sort.Slice(findings, func(i, j int) bool {
257			if findings[i].Severity != findings[j].Severity {
258				return findings[i].Severity > findings[j].Severity
259			}
260			return findings[i].TxHash < findings[j].TxHash
261		})
262		return findings
263	}
264	
265	// record is the archived form of a block: the report plus the canonical
266	// swaps, so a later import can detect content conflicts. Version carries
267	// the full rule parameters used for the findings; it is nil only in
268	// archives written before rule versions existed, which are interpreted
269	// under the built-in rules.
270	type record struct {
271		ChainID     string          `json:"chainId"`
272		BlockHash   string          `json:"blockHash"`
273		BlockNumber int64           `json:"blockNumber"`
274		Swaps       []Swap          `json:"swaps"`
275		Findings    []ReportFinding `json:"findings"`
276		Version     *RuleVersion    `json:"version,omitempty"`
277	}
278	
279	func (r record) ruleVersion() RuleVersion {
280		if r.Version != nil {
281			return *r.Version
282		}
283		return BuiltinVersion()
284	}
285	
286	// queryRecord mirrors one archived record the way a report query reads it.
287	// Every business field is decoded normally, but the archived rule-version
288	// declaration is kept as its raw stored document. The decoded struct cannot
289	// tell a missing field, an explicit null or a wrong-typed value from a real
290	// one: decoding the embedded version into the struct would show a decayed
291	// report under silently zeroed parameters (enabled false, severity 0, a
292	// zero displacement multiplier), and — because a null or incomplete
293	// declaration carries no usable id — risk explaining it as the built-in
294	// rules. A zero-length Version means the "version" key is absent entirely
295	// (a value-type RawMessage is left untouched for a missing key), which
296	// alone is the legacy, pre-version format interpreted under the built-in
297	// rules; any present value — the bytes "null", {} or an object — is kept
298	// byte for byte and must be re-validated from those bytes before the
299	// report is shown.
300	type queryRecord struct {
301		ChainID     string          `json:"chainId"`
302		BlockHash   string          `json:"blockHash"`
303		BlockNumber int64           `json:"blockNumber"`
304		Swaps       []Swap          `json:"swaps"`
305		Findings    []ReportFinding `json:"findings"`
306		Version     json.RawMessage `json:"version"`
307	}
308	
309	// archivedReportVersion proves the version declaration embedded in an
310	// archived record still satisfies every registration rule, re-validating
311	// the raw document with the same parser registrations pass. A wholly
312	// absent "version" key is the only legacy shape and means the built-in
313	// rules; anything actually saved — null, an empty object, an incomplete
314	// declaration, a wrong type, an out-of-range number, an unknown or
315	// duplicated field — is corruption rather than a zero-filled or built-in
316	// parameter set. An id of "builtin" names the same saved declaration and
317	// is validated just like any other id; it never bypasses the check.
318	func archivedReportVersion(raw json.RawMessage) (RuleVersion, error) {
319		if len(raw) == 0 {
320			return BuiltinVersion(), nil
321		}
322		return ParseRuleVersion(raw)
323	}
324	
325	// proveAllReportsIntact re-validates every archived report's embedded
326	// version declaration from that record's raw stored bytes with exactly the
327	// integrity proof a report query enforces (archivedReportVersion plus
328	// corruptReportError). It is the shared gate every operation that rewrites
329	// an archive must pass while holding its write lock — suppression
330	// registration and revocation alike. A wholly absent "version" key is the
331	// one legacy shape and means the built-in rules; anything actually saved —
332	// null, an empty object, an incomplete declaration, a wrong type, an
333	// out-of-range number, an unknown rule or field, or a field repeated in one
334	// object, the case-folded and escaped spellings included — fails as
335	// ErrCorruptVersion naming the report's chain and block, the readable saved
336	// version id and the offending rule or field. Every record is opened: a
337	// report on another chain, outside the operation's coverage, or carrying no
338	// conclusions is never skipped, and a legal declaration is used exactly as
339	// saved, never completed from defaults, the currently enabled or a same-id
340	// registered version. A record whose bytes are not even a JSON object is
341	// whole-archive corruption rather than one report's damaged declaration.
342	func proveAllReportsIntact(data replayArchiveDoc) error {
343		for j, rawRec := range data.Records {
344			var rec queryRecord
345			if err := json.Unmarshal(rawRec, &rec); err != nil {
346				return fmt.Errorf("archive is corrupted: record %d: %w", j, err)
347			}
348			if _, verr := archivedReportVersion(rec.Version); verr != nil {
349				return corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, verr)
350			}
351		}
352		return nil
353	}
354	
355	// corruptReportError names the chain and block a failed report query
356	// targets, the saved version identifier when the document still carries a
357	// readable one (so corruption is not mistaken for an unregistered
358	// version), and the offending rule or field from the validation failure.
359	// It wraps both ErrCorruptVersion and the underlying cause (for example
360	// ErrDuplicateField).
361	func corruptReportError(chainID, blockHash string, raw json.RawMessage, cause error) error {
362		if id := identifiableVersionID(raw); id != "unidentifiable version" {
363			return fmt.Errorf("%w: archived report for chain %s block %s uses version %q: %w",
364				ErrCorruptVersion, chainID, blockHash, id, cause)
365		}
366		return fmt.Errorf("%w: archived report for chain %s block %s: %w",
367			ErrCorruptVersion, chainID, blockHash, cause)
368	}
369	
370	// reportFromQueryRecord builds the Report presented for one archived
371	// record, proving the complete version declaration the record archived
372	// before any conclusion is shown. A report query and an identical reimport
373	// take this same path, so a re-imported block whose content matches the
374	// archive is held to exactly the standard of a standalone report query:
375	// a wholly absent version key is the one legacy shape and means the
376	// built-in rules, while a declaration actually saved as null, as an empty
377	// object, only in part, with a wrong type or an out-of-range number, an
378	// unknown or repeated field — an id of "builtin" included — fails as
379	// ErrCorruptVersion naming the chain, the block, the readable saved id
380	// and the offending rule or field. The parameters are never zero-filled,
381	// borrowed from the enabled or a registered version, or re-detected; the
382	// archived findings, evidence and swap count are returned as stored.
383	func reportFromQueryRecord(rec *queryRecord) (Report, error) {
384		version, err := archivedReportVersion(rec.Version)
385		if err != nil {
386			return Report{}, corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, err)
387		}
388		return Report{
389			ChainID:     rec.ChainID,
390			BlockHash:   rec.BlockHash,
391			BlockNumber: rec.BlockNumber,
392			SwapCount:   len(rec.Swaps),
393			Version:     version,
394			Findings:    rec.Findings,
395		}, nil
396	}
397	
398	func (r record) report() Report {
399		return Report{
400			ChainID:     r.ChainID,
401			BlockHash:   r.BlockHash,
402			BlockNumber: r.BlockNumber,
403			SwapCount:   len(r.Swaps),
404			Version:     r.ruleVersion(),
405			Findings:    r.Findings,
406		}
407	}
408	
409	const (
410		archiveFileName = "archive.json"
411		lockFileName    = "lock"
412	)
413	
414	type archiveData struct {
415		Records []record `json:"records"`
416		// Versions and EnabledVersion are absent in archives written before
417		// rule versions existed; such archives run the built-in rules.
418		Versions       []RuleVersion `json:"versions,omitempty"`
419		EnabledVersion string        `json:"enabledVersion,omitempty"`
420		// Suppressions and AlertRecords are absent in archives written before
421		// offline alerting existed; such archives simply have no registered
422		// conditions and no processing history.
423		Suppressions []Suppression      `json:"suppressions,omitempty"`
424		AlertRecords []ProcessingRecord `json:"alerts,omitempty"`
425		// Reviews is absent in archives written before manual reviews existed;
426		// every conclusion then behaves as unreviewed.
427		Reviews []ReviewObject `json:"reviews,omitempty"`
428	}
429	
430	// readArchiveBytes returns the exact bytes of the archive file, or nil
431	// when no archive exists yet.
432	func readArchiveBytes(dir string) ([]byte, error) {
433		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
434		if errors.Is(err, os.ErrNotExist) {
435			return nil, nil
436		}
437		if err != nil {
438			return nil, err
439		}
440		return raw, nil
441	}
442	
443	func readArchive(dir string) (archiveData, error) {
444		raw, err := readArchiveBytes(dir)
445		if err != nil {
446			return archiveData{}, err
447		}
448		if raw == nil {
449			return archiveData{Records: []record{}}, nil
450		}
451		var data archiveData
452		if err := json.Unmarshal(raw, &data); err != nil {
453			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
454		}
455		return data, nil
456	}
457	
458	// replayArchiveDoc mirrors the archive file the way a replay reads and
459	// writes it: every record and every registered version is kept as its raw
460	// stored document, while suppressions, alert records and reviews are fully
461	// decoded. A corrupt document — a wrong-typed field, say — then cannot
462	// break the read or masquerade as whole-archive corruption; the version
463	// this run selects is judged on its own by intactVersion, and an already
464	// archived block whose content matches the input is judged on its own from
465	// its record's raw bytes exactly the way a report query proves it, rather
466	// than decoded into silently zeroed parameters or a null-explained
467	// built-in report. Entries the run does not touch are written back byte
468	// for byte: a replay never repairs, completes or drops a stored record or
469	// version, not even a corrupt one.
470	type replayArchiveDoc struct {
471		Records        []json.RawMessage  `json:"records"`
472		Versions       []json.RawMessage  `json:"versions,omitempty"`
473		EnabledVersion string             `json:"enabledVersion,omitempty"`
474		Suppressions   []Suppression      `json:"suppressions,omitempty"`
475		AlertRecords   []ProcessingRecord `json:"alerts,omitempty"`
476		Reviews        []ReviewObject     `json:"reviews,omitempty"`
477	}
478	
479	// writeArchiveAtomic replaces the archive file in one rename, so a crash
480	// can only expose the previous or the next complete commit, never a half
481	// written file.
482	func writeArchiveAtomic(dir string, data any) error {
483		raw, err := json.MarshalIndent(data, "", "  ")
484		if err != nil {
485			return err
486		}
487		tmp := filepath.Join(dir, archiveFileName+".tmp")
488		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
489		if err != nil {
490			return err
491		}
492		if _, err := f.Write(raw); err != nil {
493			f.Close()
494			os.Remove(tmp)
495			return err
496		}
497		if err := f.Sync(); err != nil {
498			f.Close()
499			os.Remove(tmp)
500			return err
501		}
502		if err := f.Close(); err != nil {
503			os.Remove(tmp)
504			return err
505		}
506		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
507			os.Remove(tmp)
508			return err
509		}
510		if d, err := os.Open(dir); err == nil {
511			d.Sync()
512			d.Close()
513		}
514		return nil
515	}
516	
517	// lockArchive takes an flock on the archive's lock file. The lock is
518	// released automatically if the process dies, so no stale locks survive.
519	func lockArchive(dir string, how int) (*os.File, error) {
520		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
521		if err != nil {
522			return nil, err
523		}
524		if err := syscall.Flock(int(f.Fd()), how); err != nil {
525			f.Close()
526			if errors.Is(err, syscall.EWOULDBLOCK) {
527				return nil, ErrBusy
528			}
529			return nil, err
530		}
531		return f, nil
532	}
533	
534	type parsedBlock struct {
535		line  int
536		block Block
537	}
538	
539	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
540		var out []parsedBlock
541		reader := bufio.NewReader(r)
542		lineNo := 0
543		for {
544			raw, err := reader.ReadBytes('\n')
545			if len(raw) > 0 {
546				lineNo++
547			}
548			if text := strings.TrimSpace(string(raw)); text != "" {
549				block, perr := parseBlock(text)
550				if perr != nil {
551					return nil, &LineError{Line: lineNo, Err: perr}
552				}
553				out = append(out, parsedBlock{line: lineNo, block: block})
554			}
555			if err == io.EOF {
556				return out, nil
557			}
558			if err != nil {
559				return nil, err
560			}
561		}
562	}
563	
564	// ReplayFile imports the line-delimited blocks in inputPath into the
565	// archive at dir and returns one report per distinct block, in order of
566	// first appearance. New blocks are judged under the archive's currently
567	// enabled rule version; that version's stored document must still satisfy
568	// the registration rules in full, or the whole replay fails with
569	// ErrCorruptVersion before any report is produced.
570	func ReplayFile(inputPath, dir string) ([]Report, error) {
571		return replayFile(inputPath, dir, "")
572	}
573	
574	// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
575	// version instead of the archive's enabled one. The named version's stored
576	// document must still satisfy the registration rules in full; a corrupt
577	// one fails the whole replay with ErrCorruptVersion rather than judging
578	// under zeroed or substituted parameters.
579	func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
580		if versionID == "" {
581			return nil, errors.New("version id must not be empty")
582		}
583		return replayFile(inputPath, dir, versionID)
584	}
585	
586	func replayFile(inputPath, dir, versionID string) ([]Report, error) {
587		f, err := os.Open(inputPath)
588		if err != nil {
589			return nil, err
590		}
591		defer f.Close()
592		return doReplay(f, dir, versionID)
593	}
594	
595	// Replay parses, validates and archives blocks from r under the archive's
596	// currently enabled rule version. Every line is checked before anything is
597	// written; any failure leaves the archive untouched. New reports are
598	// committed together in a single atomic write. The selected version's
599	// stored document is re-validated before any block is judged: a corrupt
600	// version fails the whole replay with ErrCorruptVersion — never a
601	// substituted or zeroed parameter set — even when no input block would
602	// have triggered the damaged rule.
603	//
604	// A block that is already archived and arrives with identical content is
605	// not re-judged: its original report is returned. Before that report is
606	// returned the declaration the record archived is proved from its raw
607	// bytes by exactly the standard a standalone report query (Query)
608	// enforces — a non-empty id, both rules each declaring a boolean enabled
609	// and an integer severity 1-5, and a displacement multiplier 2-100 —
610	// rather than trusted because this run's own version is legal. A
611	// declaration saved as null, as an empty object, only in part, with a
612	// wrong type or out-of-range number, an unknown rule or field, or a field
613	// repeated in one object (the field-name folding and escapes included,
614	// even when both values agree) fails the whole replay with
615	// ErrCorruptVersion; an explicit enabled:false is a legal off state but a
616	// disabled rule still has to be declared completely. Only a wholly absent
617	// version key — the pre-version legacy shape — is explained by the
618	// built-in rules; a written "builtin" id is validated like every other.
619	// On failure no report is returned, no same-batch new block is saved and
620	// no archived content changes, regardless of where the corrupt old block
621	// sits relative to the new ones. An intact old report is returned with
622	// its originally saved conclusions, evidence, swap count and full
623	// parameters, never re-detected and never completed from the currently
624	// enabled or a same-id registered version; its historical id need not
625	// still be registered.
626	func Replay(input io.Reader, dir string) ([]Report, error) {
627		return doReplay(input, dir, "")
628	}
629	
630	// ReplayWithVersion is Replay under an explicitly registered rule version
631	// instead of the archive's enabled one, with the same integrity check: a
632	// corrupt stored version document fails the whole replay with
633	// ErrCorruptVersion before any report is produced.
634	func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
635		if versionID == "" {
636			return nil, errors.New("version id must not be empty")
637		}
638		return doReplay(input, dir, versionID)
639	}
640	
641	func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
642		parsed, err := parseBlocks(input)
643		if err != nil {
644			return nil, err
645		}
646	
647		// Collapse repeated identities within this file, keeping first
648		// appearance order; conflicting content rejects the whole file.
649		type occurrence struct {
650			block Block
651			line  int
652		}
653		order := []occurrence{}
654		firstSeen := make(map[blockID]int)
655		for _, p := range parsed {
656			id := blockID{p.block.ChainID, p.block.BlockHash}
657			if first, ok := firstSeen[id]; ok {
658				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
659					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
660						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
661				}
662				continue
663			}
664			firstSeen[id] = len(order)
665			order = append(order, occurrence{block: p.block, line: p.line})
666		}
667	
668		if err := os.MkdirAll(dir, 0o755); err != nil {
669			return nil, err
670		}
671		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
672		if err != nil {
673			return nil, err
674		}
675		defer lock.Close()
676	
677		// Decode with every stored record and registered version kept as its
678		// raw stored document, so a wrong-typed field in one entry is that
679		// entry's corruption, not whole-archive corruption: the selected
680		// version's document is re-validated from its bytes the same way a
681		// single-block comparison proves its version intact, and each already
682		// archived block this run re-imports is proved from its record's raw
683		// bytes the same way a standalone report query proves it, rather than
684		// decoded into silently zeroed parameters or a null-explained
685		// built-in report.
686		raw, err := readArchiveBytes(dir)
687		if err != nil {
688			return nil, err
689		}
690		data := replayArchiveDoc{Records: []json.RawMessage{}}
691		if raw != nil {
692			if err := json.Unmarshal(raw, &data); err != nil {
693				return nil, fmt.Errorf("archive is corrupted: %w", err)
694			}
695		}
696		// Resolve the version once, while the exclusive lock is held: every
697		// new block in this run is judged under the same rules even if another
698		// process enables a different version right after we finish. The
699		// selected version's stored document must still satisfy the
700		// registration rules in full; a corrupt one fails the whole replay
701		// with ErrCorruptVersion here, before any block is judged, any report
702		// is produced or anything is written — even when the input is empty,
703		// holds only blocks already archived, or would never trigger the
704		// damaged rule. The corrupt content is never replaced by the enabled
705		// version, the built-in rules or defaults.
706		version, err := resolveReplayVersion(data, versionID)
707		if err != nil {
708			return nil, err
709		}
710		// Index the stored records by block identity with their decoded
711		// content; the embedded version stays raw until an identical reimport
712		// actually has to present that record's report, when its saved
713		// declaration is proved exactly as a report query would.
714		stored := make([]queryRecord, len(data.Records))
715		archived := make(map[blockID]int, len(data.Records))
716		for i, rawRec := range data.Records {
717			var qr queryRecord
718			if err := json.Unmarshal(rawRec, &qr); err != nil {
719				return nil, fmt.Errorf("archive is corrupted: record %d: %w", i, err)
720			}
721			stored[i] = qr
722			archived[blockID{qr.ChainID, qr.BlockHash}] = i
723		}
724	
725		reports := make([]Report, 0, len(order))
726		newRecords := []json.RawMessage{}
727		for _, occ := range order {
728			id := blockID{occ.block.ChainID, occ.block.BlockHash}
729			if idx, ok := archived[id]; ok {
730				rec := stored[idx]
731				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
732					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
733						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
734				}
735				// Identical re-import: return the original report, add nothing.
736				// The saved declaration is held to the standard of a standalone
737				// report query before any conclusion is returned — never read as
738				// built-in from a null version or as zeroed parameters from an
739				// incomplete one, and never completed from the version this run
740				// selected. A corrupt declaration fails the whole batch here,
741				// before a single new block is committed, whether the old block
742				// appears before or after the new ones.
743				report, perr := reportFromQueryRecord(&rec)
744				if perr != nil {
745					return nil, &LineError{Line: occ.line, Err: perr}
746				}
747				reports = append(reports, report)
748				continue
749			}
750			rec := record{
751				ChainID:     occ.block.ChainID,
752				BlockHash:   occ.block.BlockHash,
753				BlockNumber: occ.block.BlockNumber,
754				Swaps:       occ.block.Swaps,
755				Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
756				Version:     &version,
757			}
758			rawRec, perr := json.Marshal(rec)
759			if perr != nil {
760				return nil, perr
761			}
762			newRecords = append(newRecords, rawRec)
763			reports = append(reports, rec.report())
764		}
765		// All blocks passed — new and identical alike — so commit the new
766		// records once, leaving every stored record's raw bytes untouched.
767		if len(newRecords) > 0 {
768			data.Records = append(data.Records, newRecords...)
769			if err := writeArchiveAtomic(dir, data); err != nil {
770				return nil, err
771			}
772		}
773		return reports, nil
774	}
775	
776	// resolveReplayVersion picks the rule version for one replay run — the
777	// explicitly requested one, or the archive's currently enabled version —
778	// and proves its stored archive document still satisfies every
779	// registration rule, re-validating the raw document with the same parser
780	// registrations pass. The decoded struct cannot do this: a missing
781	// enabled, severity or multiplier field unmarshals as the zero value and
782	// is indistinguishable from an explicitly declared one, and a zero
783	// displacement multiplier even crashes detection. An explicitly declared
784	// false or any in-range value is valid; a missing or null field, a wrong
785	// type or an out-of-range number makes the version corrupt, and the
786	// failure names the version and the offending rule or field. Archives
787	// written before rule versions existed have no enabled marker and run the
788	// built-in rules; the built-in version is constructed in code and always
789	// intact.
790	func resolveReplayVersion(data replayArchiveDoc, versionID string) (RuleVersion, error) {
791		id := versionID
792		if id == "" {
793			id = data.EnabledVersion
794			if id == "" {
795				return BuiltinVersion(), nil
796			}
797		}
798		return intactVersion(data.Versions, id)
799	}
800	
801	// queryArchiveDoc mirrors just the records a report query reads, keeping
802	// each record's embedded version declaration as its raw stored document —
803	// the same shape registered versions are kept in everywhere else — so a
804	// wrong-typed field in one report's declaration fails that report's query
805	// rather than breaking the whole-archive decode or decoding into silently
806	// zeroed parameters.
807	type queryArchiveDoc struct {
808		Records []queryRecord `json:"records"`
809	}
810	
811	// Query returns the archived report for one block identity. It only reads
812	// the archive; the original input file is not needed, and neither a
813	// successful nor a failed query rewrites anything.
814	//
815	// Before the report is returned, the complete version declaration the
816	// report archived is re-validated from its raw bytes with the same proof
817	// registration, enable, comparison, evaluation and replay demand: a
818	// non-empty version identifier, both the sandwich and displacement rules
819	// each with a boolean enabled and an integer severity in 1-5, and the
820	// displacement multiplier an integer in 2-100. A missing or null field or
821	// rule object, a wrong type, an out-of-range number, an unknown field or
822	// rule, or a field declared twice in one object (an exact repeat, an
823	// escaped spelling or a case-only spelling that names the same field —
824	// even when both values agree) makes the saved declaration corrupt. An
825	// explicit enabled:false is a legal off state, not damage; the disabled
826	// rule still has to carry complete, in-range parameters.
827	//
828	// Only an old-format record with no "version" key at all keeps the
829	// original built-in interpretation. A declaration actually saved as null,
830	// as an empty object or only in part is corruption, and an id of
831	// "builtin" is validated like every other id rather than bypassing the
832	// check. On corruption Query fails with ErrCorruptVersion naming the
833	// target chain and block, the readable saved version id and the offending
834	// rule or field; it never zero-fills the parameters, explains them as
835	// built-in, or substitutes parameters from the currently enabled or a
836	// registered version. The report uses the parameters it archived and is
837	// never re-detected. A block that was never archived stays
838	// ErrUnknownBlock.
839	func Query(dir, chainID, blockHash string) (Report, error) {
840		if _, err := os.Stat(dir); err != nil {
841			if errors.Is(err, os.ErrNotExist) {
842				return Report{}, ErrUnknownBlock
843			}
844			return Report{}, err
845		}
846		lock, err := lockArchive(dir, syscall.LOCK_SH)
847		if err != nil {
848			return Report{}, err
849		}
850		defer lock.Close()
851	
852		raw, err := readArchiveBytes(dir)
853		if err != nil {
854			return Report{}, err
855		}
856		var doc queryArchiveDoc
857		if len(raw) > 0 {
858			if err := json.Unmarshal(raw, &doc); err != nil {
859				return Report{}, fmt.Errorf("archive is corrupted: %w", err)
860			}
861		}
862		idx := -1
863		for i := range doc.Records {
864			if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
865				idx = i
866				break
867			}
868		}
869		if idx < 0 {
870			return Report{}, ErrUnknownBlock
871		}
872		rec := &doc.Records[idx]
873		return reportFromQueryRecord(rec)
874	}
875

