17	// twoBlockInput holds one sandwich (severity 3, pool p1, victim 0xv) and
18	// one displacement (severity 2, pool p2, victim 0xd):
19	//
20	//	p1: 0xf (gas 90) / 0xv (gas 10) / 0+k (gas 80)  -> sandwich on 0xv
21	//	p2: 0+w (gas 50) / 0xd (gas 10)                 -> displacement on 0xd
22	const twoFindingsInput = `{"chainId":"1","blockHash":"0xa","blockNumber":10,` +
23		`"swaps":[` +
