27		`{"TxHash":"0+w","Pool":"p2","Trader":"whale","In":1,"Out":1,"GasPrice":50,"Index":3},` +
28		`{"TxHash":"0xd","Pool":"p2","Trader":"user","In":1,"Out":1,"GasPrice":10,"Index":4}]}`
29	
30	func mustReplay(t *testing.T, dir, input string) {
31		t.Helper()
32		if _, err := Replay(strings.NewReader(input), dir); err != nil {
33			t.Fatalf("Replay: %v", err)
