42		if err != nil {
43			t.Fatalf("GenerateAlerts: %v", err)
44		}
45		if len(got) != 1 {
46			t.Fatalf("got %d records, want 1 (only sandwich meets severity 3): %+v", len(got), got)
47		}
48		r := got[0]
49		if r.Status != AlertStatusAlert {
50			t.Fatalf("status = %q, want alert", r.Status)
51		}
52		if r.ChainID != "1" || r.BlockHash != "0xa" || r.BlockNumber != 10 {
53			t.Fatalf("bad block identity: %+v", r)
54		}
55		if r.Pool != "p1" || r.Channel != "ops" {
56			t.Fatalf("bad pool/channel: %+v", r)
57		}
58		if r.Finding.Kind != "sandwich" || r.Finding.TxHash != "0xv" || r.Finding.Severity != 3 {
59			t.Fatalf("bad finding: %+v", r.Finding)
60		}
61		if r.MinSeverity != 3 {
62			t.Fatalf("MinSeverity = %d, want 3", r.MinSeverity)
63		}
