66		}
67		if len(r.Finding.Evidence) != 3 || r.Finding.Evidence[1].TxHash != "0xv" {
68			t.Fatalf("raw evidence not preserved: %+v", r.Finding.Evidence)
69		}
70		if r.Suppressions == nil || len(r.Suppressions) != 0 {
71			t.Fatalf("alerts carry an empty suppression list, got %+v", r.Suppressions)
72		}
73	}
74	
75	func TestGenerateAlertsEmptyIsArray(t *testing.T) {
76		dir := t.TempDir()
77		mustReplay(t, dir, twoFindingsInput)
78		got, err := GenerateAlerts(dir, "1", "ops", 100, 200, 1)
79		if err != nil {
80			t.Fatal(err)
81		}
82		if len(got) != 0 {
83			t.Fatalf("got %d records, want 0", len(got))
84		}
85		raw, err := json.Marshal(got)
86		if err != nil {
87			t.Fatal(err)
88		}
89		if string(raw) != "[]" {
90			t.Fatalf("empty result must serialize as [], got %s", raw)
91		}
92	}
93	
94	func TestGenerateAlertsIdempotent(t *testing.T) {
95		dir := t.TempDir()
96		mustReplay(t, dir, twoFindingsInput)
97	
98		first, err := GenerateAlerts(dir, "1", "ops", 10, 10, 3)
99		if err != nil {
100			t.Fatal(err)
101		}
102		if len(first) != 1 {
103			t.Fatalf("first run: got %d, want 1", len(first))
104		}
105		// Repeated generation, wider range, overlapping range, and a "restart"
106		// (fresh call against the same on-disk archive) create nothing new while
107		// the threshold stays at 3 (the severity-2 displacement is simply
108		// ineligible, not processed).
109		for _, bounds := range [][2]uint64{{10, 10}, {0, 100}, {5, 15}, {10, 10}} {
110			again, err := GenerateAlerts(dir, "1", "ops", bounds[0], bounds[1], 3)
111			if err != nil {
112				t.Fatal(err)
113			}
114			if len(again) != 0 {
115				t.Fatalf("range %d-%d re-generated %d records: %+v", bounds[0], bounds[1], len(again), again)
116			}
117		}
118		// Re-importing the same block still cannot make the sandwich alert twice.
119		mustReplay(t, dir, twoFindingsInput)
120		again, err := GenerateAlerts(dir, "1", "ops", 0, 100, 3)
121		if err != nil {
122			t.Fatal(err)
123		}
124		if len(again) != 0 {
125			t.Fatalf("re-import re-generated records: %+v", again)
126		}
127		// Lowering the threshold backfills the displacement once, then never again.
128		backfill, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
129		if err != nil {
130			t.Fatal(err)
131		}
132		if len(backfill) != 1 || backfill[0].Finding.Kind != "displacement" {
133			t.Fatalf("threshold backfill: got %+v, want the one displacement", backfill)
134		}
135		after, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
136		if err != nil {
137			t.Fatal(err)
138		}
139		if len(after) != 0 {
140			t.Fatalf("backfilled displacement re-generated: %+v", after)
141		}
142	}
