608	func TestParseSuppressionDuplicateFields(t *testing.T) {
609		base := func(extra ...string) string {
610			fields := []string{
611				`"id":"s"`, `"chainId":"1"`, `"pool":"p"`, `"kind":"sandwich"`,
612				`"channel":"c"`, `"startHeight":1`, `"endHeight":2`, `"reason":"r"`,
613			}
614			return "{" + strings.Join(append(fields, extra...), ",") + "}"
615		}
616		bad := []struct {
617			name string
618			spec string
619			want string
620		}{
621			{"same field twice", base(`"channel":"c"`, `"channel":"c2"`), "channel"},
622			{"same field same value", base(`"channel":"c"`, `"channel":"c"`), "channel"},
623			{"case variant", base(`"channel":"ops"`, `"CHANNEL":"audit"`), "channel"},
624			{"escaped name", base(`"pool":"p"`, `"poo\u006c":"p2"`), "pool"},
625			{"unicode-escaped name", base(`"kind":"sandwich"`, `"k\u0069nd":"displacement"`), "kind"},
626			{"duplicate height", base(`"startHeight":1`, `"startHeight":5`), "startHeight"},
627		}
628		for _, tc := range bad {
