639				}
640			})
641		}
642		// A single case-variant declaration stays legal and is stored verbatim.
643		s, err := ParseSuppression([]byte(`{"id":"s","chainId":"1","pool":"p","kind":"sandwich","CHANNEL":" Ops ","startHeight":1,"endHeight":2,"reason":"r"}`))
644		if err != nil {
