1075		// Condition covers heights 100..200; the block at height 10 is out of
1076		// range either way. Use a covering condition to establish history first.
1077		spec := `{"id":"s1","chainId":"1","pool":"p1","kind":"sandwich","channel":"ops","startHeight":0,"endHeight":200,"reason":"r"}`
1078		if _, _, err := RegisterSuppression(dir, []byte(spec)); err != nil {
1079			t.Fatal(err)
1080		}
1081		// Before the revocation: block 0xa at height 10 is processed suppressed.
1082		first, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
1083		if err != nil {
1084			t.Fatal(err)
1085		}
1086		var historical *ProcessingRecord
1087		for i := range first {
1088			if first[i].Finding.TxHash == "0xv" {
1089				historical = &first[i]
1090			}
1091		}
1092		if historical == nil || historical.Status != AlertStatusSuppressed ||
1093			len(historical.Suppressions) != 1 || historical.Suppressions[0].ID != "s1" {
1094			t.Fatalf("precondition: want s1-suppressed record, got %+v", first)
1095		}
1096		if _, _, err := RevokeSuppression(dir, "s1"); err != nil {
1097			t.Fatal(err)
1098		}
1099		// A different block at the same height, imported long after the archive
1100		// contained the original: revocation still applies even though the block
1101		// "was already archived" is irrelevant — what matters is processing time.
1102		other := strings.Replace(twoFindingsInput, `"blockHash":"0xa"`, `"blockHash":"0xb"`, 1)
1103		other = strings.Replace(other, `"0xv"`, `"0xv2"`, -1)
1104		mustReplay(t, dir, other)
1105		got, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
1106		if err != nil {
1107			t.Fatal(err)
1108		}
1109		var later *ProcessingRecord
1110		for i := range got {
1111			if got[i].BlockHash == "0xb" {
1112				later = &got[i]
1113			}
1114		}
1115		if later == nil {
1116			t.Fatalf("new block produced no records: %+v", got)
1117		}
1118		for _, r := range got {
1119			if r.Status == AlertStatusSuppressed {
1120				t.Fatalf("after revocation nothing should be suppressed: %+v", r)
1121			}
1122		}
1123		// The historical record is unchanged and still visible in history.
1124		hist, err := AlertHistory(dir, "1", "ops", 0, 100)
1125		if err != nil {
1126			t.Fatal(err)
1127		}
1128		var seen *ProcessingRecord
1129		for i := range hist {
1130			if hist[i].BlockHash == "0xa" && hist[i].Finding.TxHash == "0xv" {
1131				seen = &hist[i]
1132			}
1133		}
1134		if seen == nil || seen.Status != AlertStatusSuppressed ||
1135			len(seen.Suppressions) != 1 || seen.Suppressions[0].ID != "s1" {
1136			t.Fatalf("historical record altered by revocation: %+v", seen)
1137		}
1138		// Re-generating over overlapping ranges still skips processed findings.
1139		again, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
1140		if err != nil {
1141			t.Fatal(err)
1142		}
1143		if len(again) != 0 {
1144			t.Fatalf("overlapping generation reprocessed findings: %+v", again)
1145		}
1146	}
