331			t.Fatalf("error = %v, want ErrCorruptVersion", err)
332		}
333		if !strings.Contains(err.Error(), "archived report for chain 1 block 0xblk") ||
334			!strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "multiplier") {
335			t.Fatalf("failure must identify the historical declaration, got %v", err)
336		}
337	}
338	
339	// TestCompareLegacyRecordStillBuiltin proves the single carve-out is
340	// unchanged by the fix: a record with no version key at all compares
341	// with the built-in rules on the historical side and its stored
342	// conclusions and swap evidence intact.
343	func TestCompareLegacyRecordStillBuiltin(t *testing.T) {
344		dir := t.TempDir()
345		legacy := `{"records":[` +
346			`{"chainId":"1","blockHash":"0old","blockNumber":5,` +
347			`"swaps":[` +
348			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
349			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
350			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
351			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
352			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
353			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
354			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
355		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
356			t.Fatal(err)
357		}
358		register(t, dir, candidateVersionSpec)
359		result, err := Compare(dir, "1", "0old", "candC")
360		if err != nil {
361			t.Fatalf("legacy record must compare under builtin: %v", err)
362		}
363		if result.OriginalVersion != BuiltinVersion() {
364			t.Fatalf("historical side = %+v, want builtin", result.OriginalVersion)
365		}
366		if len(result.OriginalFindings) != 1 ||
367			result.OriginalFindings[0].Kind != "sandwich" ||
368			result.OriginalFindings[0].Severity != 3 {
369			t.Fatalf("legacy findings damaged: %+v", result.OriginalFindings)
370		}
371		if len(result.Swaps) != 3 {
372			t.Fatalf("legacy swap evidence damaged: %+v", result.Swaps)
373		}
374	}
