1	package mevwatch
2	
3	// Regression coverage for `reviews history` (ReviewHistoryQuery) against
4	// an archived report whose saved rule-version declaration has decayed
5	// since the report was written. Once a query hits the archived original
6	// conclusion it must first prove — exactly the way a `report` query does —
7	// that the declaration the report archived still carries a non-empty id,
8	// both rules with a boolean enabled and an integer severity 1-5, and a
9	// displacement multiplier 2-100. A written null used to be explained as
10	// the built-in rules and an incomplete declaration used to come back with
11	// silently zeroed parameters. Only an old-format record with no version
12	// key at all keeps the built-in interpretation. On corruption the whole
13	// query fails with ErrCorruptVersion — no history JSON, no partial
14	// original — naming the target chain, the block, the readable saved
15	// version id and the offending rule or field, and leaves the archive
16	// untouched.
17	
18	import (
19		"encoding/json"
20		"errors"
21		"os"
22		"path/filepath"
23		"reflect"
24		"strings"
25		"testing"
26	)
27	
28	// historyTarget is the conclusion the setupCorruptCompareArchive block
29	// carries: under candC (sandwich off, displacement severity 4 multiplier
30	// 2) swaps 0xf (gas 40) and 0xv (gas 10) produce one displacement hit on
31	// 0xv — the exact shape that used to decode a decayed zero multiplier as
32	// a real parameter set.
33	const (
34		historyTargetTx   = "0xv"
35		historyTargetKind = SuppressDisplacement
36	)
37	
38	// assertHistoryRefused runs one failing ReviewHistoryQuery and pins the
39	// failure shape: ErrCorruptVersion wrapping the cause, never an
40	// unknown-conclusion misread, naming the target chain, block and every
41	// required extra substring, returning no partial history and leaving the
42	// archive byte-identical.
43	func assertHistoryRefused(t *testing.T, dir, chain, hash, tx, kind string, want ...string) {
44		t.Helper()
45		before := readArchiveFile(t, dir)
46		hist, err := ReviewHistoryQuery(dir, chain, hash, tx, kind)
47		if err == nil {
48			t.Fatalf("corrupt declaration returned history: %+v", hist)
49		}
50		if !errors.Is(err, ErrCorruptVersion) {
51			t.Fatalf("error = %v, want ErrCorruptVersion", err)
52		}
53		if errors.Is(err, ErrUnknownVersion) {
54			t.Fatalf("corrupt declaration misreported as an unknown version: %v", err)
55		}
56		if !reflect.DeepEqual(hist, ReviewHistory{}) {
57			t.Fatalf("corrupt declaration returned a partial history: %+v", hist)
58		}
59		msg := err.Error()
60		for _, sub := range append([]string{chain, hash}, want...) {
61			if !strings.Contains(msg, sub) {
62				t.Fatalf("error %q must name %q", msg, sub)
63			}
64		}
65		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
66			t.Fatalf("failed history query changed the archive")
67		}
68		// No partial repair: a second attempt fails the same way.
69		if _, err := ReviewHistoryQuery(dir, chain, hash, tx, kind); !errors.Is(err, ErrCorruptVersion) {
70			t.Fatalf("second history query did not fail the same way: %v", err)
71		}
72	}
73	
74	// TestReviewHistoryCorruptSavedVersionRefused runs the full corruption
75	// matrix against the declaration embedded in the target report (the
76	// registered versions section stays intact): every way the saved document
77	// can stop satisfying the registration rules must fail the whole history
78	// query, naming chain, block, the readable saved id and the offending rule
79	// or field — with or without review data for the object.
80	func TestReviewHistoryCorruptSavedVersionRefused(t *testing.T) {
81		for _, tc := range corruptVersionCases {
82			t.Run(tc.name, func(t *testing.T) {
83				dir := setupCorruptCompareArchive(t)
84				rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
85					tc.mutate(t, ver)
86				})
87				assertHistoryRefused(t, dir, "1", "0xblk", historyTargetTx, historyTargetKind, "candC", tc.wantErr)
88			})
89		}
90	
91		// The proof is about the original conclusion, not the review data: an
92		// object carrying a current review fails exactly the same way.
93		t.Run("with review data", func(t *testing.T) {
94			dir := setupCorruptCompareArchive(t)
95			if _, err := SubmitReview(dir, reviewSub("1", "0xblk", historyTargetTx, historyTargetKind,
96				"s-1", "alice", "r", ReviewStatusReal, 0)); err != nil {
97				t.Fatal(err)
98			}
99			rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
100				storedRule(t, ver, "displacement")["multiplier"] = 0
101			})
102			assertHistoryRefused(t, dir, "1", "0xblk", historyTargetTx, historyTargetKind, "candC", "multiplier")
103		})
104	}
