106	// TestReviewHistoryNullAndEmptySavedVersionCorrupt pins the exact
107	// misread being fixed: version:null used to be explained as the built-in
108	// rules, and {} or an incomplete object used to return zeroed parameters.
109	// All of them fail; only a wholly missing version key is the legacy
110	// built-in shape.
111	func TestReviewHistoryNullAndEmptySavedVersionCorrupt(t *testing.T) {
112		cases := []struct {
113			name        string
114			value       any
115			idReachable bool
116		}{
117			{"null", nil, false},
118			{"empty object", map[string]any{}, false},
119			{"incomplete object", map[string]any{"id": "candC"}, true},
120			{"non-object number", 5, false},
121			{"non-object string", "builtin", false},
122			{"array", []any{}, false},
123		}
124		for _, tc := range cases {
125			t.Run(tc.name, func(t *testing.T) {
126				dir := setupCorruptCompareArchive(t)
127				replaceStoredReportVersion(t, dir, "1", "0xblk", tc.value)
128				want := []string{}
129				if tc.idReachable {
130					want = append(want, "candC")
131				}
132				assertHistoryRefused(t, dir, "1", "0xblk", historyTargetTx, historyTargetKind, want...)
133			})
134		}
135	}
