137	// TestReviewHistoryBuiltinIDDoesNotBypassValidation proves an id of
138	// "builtin" names the same saved declaration as any other id and is
139	// validated in full rather than substituting the in-code builtin rules.
140	func TestReviewHistoryBuiltinIDDoesNotBypassValidation(t *testing.T) {
141		dir := setupCorruptCompareArchive(t)
142	
143		builtinFull := map[string]any{
