170	// TestReviewHistoryDuplicateFieldsInSavedVersionRefused covers decay
171	// registration could never have produced: a repeated field in the saved
172	// declaration, including an escaped spelling and a case-only spelling
173	// that name the same field, even when both values agree. The raw bytes
174	// are patched directly because a JSON map cannot hold two keys.
175	func TestReviewHistoryDuplicateFieldsInSavedVersionRefused(t *testing.T) {
176		cases := []struct{ name, field string }{
177			{"exact", `"severity": 4, `},
178			{"case variant", `"Severity": 4, `},
179			{"escaped", "\"se\\u0076erity\": 4, "},
180		}
181		for _, dup := range cases {
182			t.Run(dup.name, func(t *testing.T) {
183				dir := setupCorruptCompareArchive(t)
184				path := filepath.Join(dir, archiveFileName)
185				text := string(readArchiveFile(t, dir))
186				versionsAt := strings.Index(text, `"versions":`)
187				if versionsAt < 0 {
188					t.Fatal("versions section not found")
189				}
190				at := strings.Index(text[:versionsAt], `"id": "candC"`)
191				if at < 0 {
192					t.Fatal("record's embedded candC declaration not found")
193				}
194				anchor := `"severity": 4,`
195				field := strings.Index(text[at:versionsAt], anchor)
196				if field < 0 {
197					t.Fatal("severity field not found in embedded declaration")
198				}
199				pos := at + field
200				patched := text[:pos] + dup.field + text[pos:]
201				if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
202					t.Fatal(err)
203				}
204				hist, err := ReviewHistoryQuery(dir, "1", "0xblk", historyTargetTx, historyTargetKind)
205				if err == nil {
206					t.Fatalf("duplicate-field declaration returned history: %+v", hist)
207				}
208				if !errors.Is(err, ErrCorruptVersion) || !errors.Is(err, ErrDuplicateField) {
209					t.Fatalf("err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", err)
210				}
211				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "severity") {
212					t.Fatalf("error must name candC and severity, got %v", err)
213				}
214				if after := readArchiveFile(t, dir); after == nil || !strings.Contains(string(after), dup.field) {
215					t.Fatalf("failed history query repaired the duplicate field")
216				}
217			})
218		}
219	}
