221	// TestReviewHistoryExplicitlyDisabledRulesAccepted proves enabled:false
222	// is a legal historical off state, but a disabled rule still has to carry
223	// complete, in-range parameters.
224	func TestReviewHistoryExplicitlyDisabledRulesAccepted(t *testing.T) {
225		dir := setupCorruptCompareArchive(t)
226		off := map[string]any{
227			"id": "off",
228			"rules": map[string]any{
