237		}
238		if hist.Original == nil || hist.Original.Version.ID != "off" ||
239			hist.Original.Version.Rules.Sandwich.Enabled ||
240			hist.Original.Version.Rules.Displacement.Enabled {
241			t.Fatalf("historical off state not carried: %+v", hist.Original)
242		}
243	
244		offBroken := map[string]any{
245			"id": "off",
246			"rules": map[string]any{
247				"sandwich":     map[string]any{"enabled": false, "severity": 1},
248				"displacement": map[string]any{"enabled": false, "severity": 1},
249			},
