255	// TestReviewHistoryUsesSavedParametersNotRegistry proves the original
256	// conclusion is explained by the declaration the report archived: a
257	// damaged same-id registry entry neither blocks nor completes the saved
258	// parameters, the enabled version never leaks in, an intact registry
259	// cannot rescue a corrupt report, and a saved id the registry never
260	// carried is still a valid explanation on its own.
261	func TestReviewHistoryUsesSavedParametersNotRegistry(t *testing.T) {
262		// Damage only the registered candC entry while the report's own
263		// embedded copy stays intact: the history still shows candC's saved
264		// parameters and borrows nothing from the registry.
265		dir := setupCorruptCompareArchive(t)
266		if _, err := EnableVersion(dir, "twin"); err != nil {
267			t.Fatal(err)
268		}
269		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
270			delete(storedRule(t, ver, "displacement"), "multiplier")
271		})
272		hist, err := ReviewHistoryQuery(dir, "1", "0xblk", historyTargetTx, historyTargetKind)
273		if err != nil {
274			t.Fatalf("a corrupt registry sibling must not block an intact saved report: %v", err)
275		}
276		if hist.Original == nil {
277			t.Fatal("original conclusion missing")
278		}
279		if want := mustRuleVersion(t, candidateVersionSpec); hist.Original.Version != want {
280			t.Fatalf("history borrowed registry parameters: %+v, want %+v", hist.Original.Version, want)
281		}
282	
283		// Conversely, an intact registry cannot rescue a corrupt report:
284		// damage only the embedded copy while the same-id registry entry stays
285		// intact.
286		dir2 := setupCorruptCompareArchive(t)
287		rewriteStoredReportVersion(t, dir2, "1", "0xblk", func(ver map[string]any) {
288			storedRule(t, ver, "displacement")["multiplier"] = 0
289		})
290		assertHistoryRefused(t, dir2, "1", "0xblk", historyTargetTx, historyTargetKind, "candC", "multiplier")
291	
292		// A complete declaration with an id the registry never carried stands
293		// on its own.
294		dir3 := setupCorruptCompareArchive(t)
295		stray := map[string]any{
296			"id": "never-registered",
297			"rules": map[string]any{
298				"sandwich":     map[string]any{"enabled": true, "severity": 5},
299				"displacement": map[string]any{"enabled": true, "severity": 5, "multiplier": 9},
300			},
301		}
302		replaceStoredReportVersion(t, dir3, "1", "0xblk", stray)
303		h3, err := ReviewHistoryQuery(dir3, "1", "0xblk", historyTargetTx, historyTargetKind)
304		if err != nil {
305			t.Fatalf("a complete self-contained declaration must not need registry backing: %v", err)
306		}
307		if h3.Original == nil || h3.Original.Version.ID != "never-registered" ||
308			h3.Original.Version.Rules.Displacement.Multiplier != 9 {
309			t.Fatalf("saved historical parameters not carried: %+v", h3.Original)
310		}
311	}
