313	// TestReviewHistoryCorruptSiblingDoesNotBlock proves the integrity proof
314	// is scoped to the report the query hits: a damaged declaration on
315	// another block or another chain, or a damaged registered version, never
316	// blocks the target conclusion's legal history; and an identity without a
317	// matching conclusion keeps original:null even when the block it names
318	// carries a damaged declaration.
319	func TestReviewHistoryCorruptSiblingDoesNotBlock(t *testing.T) {
320		dir := t.TempDir()
321		register(t, dir, candidateVersionSpec)
322		input := cmpBlockLine("1", "0xblk", 7,
323			cmpSwap("0xf", "p1", "w", 40, 0),
324			cmpSwap("0xv", "p1", "u", 10, 1),
325		) + "\n" + cmpBlockLine("1", "0other", 8,
326			cmpSwap("0g0", "p2", "w", 40, 2),
327			cmpSwap("0g1", "p2", "u", 10, 3),
328		) + "\n" + cmpBlockLine("2", "0xblk", 7,
329			cmpSwap("0q0", "p3", "w", 40, 4),
330			cmpSwap("0q1", "p3", "u", 10, 5),
331		) + "\n"
332		path := filepath.Join(t.TempDir(), "blocks.jsonl")
333		if err := os.WriteFile(path, []byte(input), 0o644); err != nil {
334			t.Fatal(err)
335		}
336		if _, err := ReplayFileWithVersion(path, dir, "candC"); err != nil {
337			t.Fatal(err)
338		}
339		register(t, dir, twinVersionSpec)
340	
341		// Damage only the same-chain sibling block.
342		rewriteStoredReportVersion(t, dir, "1", "0other", func(ver map[string]any) {
343			delete(storedRule(t, ver, "displacement"), "multiplier")
344		})
345		hist, err := ReviewHistoryQuery(dir, "1", "0xblk", historyTargetTx, historyTargetKind)
346		if err != nil {
347			t.Fatalf("a corrupt sibling block blocked the target: %v", err)
348		}
349		if hist.Original == nil || hist.Original.Version.ID != "candC" {
350			t.Fatalf("target original damaged: %+v", hist.Original)
351		}
352		// The damaged sibling itself still fails, scoped to its own block.
353		assertHistoryRefused(t, dir, "1", "0other", "0g1", historyTargetKind, "candC", "multiplier")
354	
355		// Damage the same-hash block on another chain: chain 1's target stays
356		// queryable, chain 2's fails on its own.
357		rewriteStoredReportVersion(t, dir, "2", "0xblk", func(ver map[string]any) {
358			storedRule(t, ver, "displacement")["severity"] = 0
359		})
360		if _, err := ReviewHistoryQuery(dir, "1", "0xblk", historyTargetTx, historyTargetKind); err != nil {
361			t.Fatalf("a corrupt other-chain record blocked the target: %v", err)
362		}
363		assertHistoryRefused(t, dir, "2", "0xblk", "0q1", historyTargetKind, "candC", "severity")
364	
365		// A damaged registry sibling never blocks an intact saved report.
366		rewriteStoredVersion(t, dir, "twin", func(ver map[string]any) {
367			storedRule(t, ver, "displacement")["multiplier"] = 1
368		})
369		if _, err := ReviewHistoryQuery(dir, "1", "0xblk", historyTargetTx, historyTargetKind); err != nil {
370			t.Fatalf("a corrupt registered version blocked the target: %v", err)
371		}
372	
373		// An identity with no matching conclusion keeps original:null even
374		// though the named block's own declaration is damaged; its review
375		// state defaults remain available.
376		ghost, err := ReviewHistoryQuery(dir, "1", "0other", "0ghost", SuppressSandwich)
377		if err != nil {
378			t.Fatalf("a non-matching identity must not open the block declaration: %v", err)
379		}
380		if ghost.Original != nil || ghost.Status != ReviewStatusUnreviewed || ghost.Version != 0 ||
381			len(ghost.Revisions) != 0 {
382			t.Fatalf("no-conclusion identity = %+v", ghost)
383		}
384	}
385	
386	// TestReviewHistoryLegacyRecordStillBuiltin proves the single carve-out:
387	// a record with no version key at all is still explained by the built-in
388	// rules, with the original conclusion, findings and swap evidence intact.
389	func TestReviewHistoryLegacyRecordStillBuiltin(t *testing.T) {
390		dir := t.TempDir()
391		legacy := `{"records":[` +
392			`{"chainId":"1","blockHash":"0old","blockNumber":5,` +
393			`"swaps":[` +
394			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
395			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
396			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
397			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
398			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
399			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
400			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
401		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
402			t.Fatal(err)
403		}
404		hist, err := ReviewHistoryQuery(dir, "1", "0old", "0v", SuppressSandwich)
405		if err != nil {
406			t.Fatalf("legacy record must be explained under builtin: %v", err)
407		}
408		if hist.Original == nil {
409			t.Fatal("original conclusion missing")
410		}
411		if hist.Original.Version != BuiltinVersion() {
412			t.Fatalf("version = %+v, want builtin", hist.Original.Version)
413		}
414		if hist.Original.Finding.TxHash != "0v" || hist.Original.Finding.Kind != SuppressSandwich ||
415			hist.Original.Finding.Severity != 3 || len(hist.Original.Finding.Evidence) != 3 {
416			t.Fatalf("legacy conclusion/evidence damaged: %+v", hist.Original.Finding)
417		}
418		if hist.Status != ReviewStatusUnreviewed || hist.Version != 0 || len(hist.Revisions) != 0 {
419			t.Fatalf("legacy default review state wrong: %+v", hist)
420		}
421	}
422	
423	// TestReviewHistorySuccessContentPreserved proves a healthy history keeps
424	// the current review status, the review version, every revision in
425	// ascending order, the original conclusion with its saved detection
426	// parameters and the complete swap evidence — with no re-detection —
427	// whether or not review data exists.
428	func TestReviewHistorySuccessContentPreserved(t *testing.T) {
429		dir := t.TempDir()
430		mustReplay(t, dir, twoFindingsInput)
431	
432		// No review data yet: defaults plus the full original under builtin.
433		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xd", SuppressDisplacement)
434		if err != nil {
435			t.Fatal(err)
436		}
437		if hist.Status != ReviewStatusUnreviewed || hist.Version != 0 || len(hist.Revisions) != 0 {
438			t.Fatalf("default review state wrong: %+v", hist)
439		}
440		if hist.Original == nil {
441			t.Fatal("original conclusion missing")
442		}
443		if hist.Original.BlockNumber != 10 ||
444			hist.Original.Finding.TxHash != "0xd" || hist.Original.Finding.Kind != SuppressDisplacement ||
445			hist.Original.Finding.Severity != 2 || len(hist.Original.Finding.Evidence) != 2 {
446			t.Fatalf("original conclusion/evidence wrong: %+v", hist.Original)
447		}
448		if hist.Original.Version != BuiltinVersion() {
449			t.Fatalf("detection version wrong: %+v", hist.Original.Version)
450		}
451	
452		submit(t, dir, reviewSub("1", "0xa", "0xd", SuppressDisplacement, "s-1", "alice", "fp", ReviewStatusFalsePositive, 0))
453		submit(t, dir, reviewSub("1", "0xa", "0xd", SuppressDisplacement, "s-2", "bob", "keep", ReviewStatusReal, 1))
454		hist, err = ReviewHistoryQuery(dir, "1", "0xa", "0xd", SuppressDisplacement)
455		if err != nil {
456			t.Fatal(err)
457		}
458		if hist.Status != ReviewStatusReal || hist.Version != 2 {
459			t.Fatalf("current state = %q/%d", hist.Status, hist.Version)
460		}
461		if len(hist.Revisions) != 2 ||
462			hist.Revisions[0].Version != 1 || hist.Revisions[0].SubmissionID != "s-1" || hist.Revisions[0].Status != ReviewStatusFalsePositive ||
463			hist.Revisions[1].Version != 2 || hist.Revisions[1].SubmissionID != "s-2" || hist.Revisions[1].Status != ReviewStatusReal {
464			t.Fatalf("revisions not ascending with full content: %+v", hist.Revisions)
465		}
466		if hist.Original.Finding.Severity != 2 ||
467			hist.Original.Version != BuiltinVersion() ||
468			len(hist.Original.Finding.Evidence) != 2 {
469			t.Fatalf("original conclusion changed across reviews: %+v", hist.Original)
470		}
471	
472		// A non-builtin saved declaration is carried with its own parameters.
473		dir2 := setupCorruptCompareArchive(t)
474		h2, err := ReviewHistoryQuery(dir2, "1", "0xblk", historyTargetTx, historyTargetKind)
475		if err != nil {
476			t.Fatal(err)
477		}
478		if h2.Original == nil {
479			t.Fatal("original conclusion missing")
480		}
481		if want := mustRuleVersion(t, candidateVersionSpec); h2.Original.Version != want {
482			t.Fatalf("saved parameters wrong: %+v want %+v", h2.Original.Version, want)
483		}
484		if h2.Original.Finding.Severity != 4 {
485			t.Fatalf("conclusion severity must stay the archived 4, got %d", h2.Original.Finding.Severity)
486		}
487	}
488	
489	// TestReviewHistoryCorruptDeclarationReadOnly proves a refused history
490	// query rewrites neither reports, reviews, the enabled marker nor the
491	// archive bytes, and the stored revisions stay reachable once the report
492	// is restored.
493	func TestReviewHistoryCorruptDeclarationReadOnly(t *testing.T) {
494		dir := setupCorruptCompareArchive(t)
495		submit(t, dir, reviewSub("1", "0xblk", historyTargetTx, historyTargetKind, "s-1", "alice", "r", ReviewStatusReal, 0))
496		corruptBytes := func() []byte {
497			rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
498				storedRule(t, ver, "displacement")["multiplier"] = 0
499			})
500			return readArchiveFile(t, dir)
501		}()
502		if _, err := ReviewHistoryQuery(dir, "1", "0xblk", historyTargetTx, historyTargetKind); !errors.Is(err, ErrCorruptVersion) {
503			t.Fatalf("expected ErrCorruptVersion")
504		}
505		after := readArchiveFile(t, dir)
506		if !reflect.DeepEqual(corruptBytes, after) {
507			t.Fatalf("failed history query modified the archive")
508		}
509		// The review object itself is untouched: the query rewrote nothing.
510		var doc rawVersionArchiveDoc
511		if err := json.Unmarshal(after, &doc); err != nil {
512			t.Fatal(err)
513		}
514		if len(doc.Reviews) != 1 || len(doc.Reviews[0].Revisions) != 1 ||
515			doc.Reviews[0].Revisions[0].SubmissionID != "s-1" {
516			t.Fatalf("review data changed: %+v", doc.Reviews)
517		}
518	}
