		ChainID:      r.ChainID,
		BlockHash:    r.BlockHash,
		BlockNumber:  r.BlockNumber,
		Pool:         r.Pool,
		Channel:      r.Channel,
		Finding:      r.Finding,
		Version:      version,
		MinSeverity:  r.MinSeverity,
		Status:       r.Status,
		Suppressions: r.Suppressions,
	}
}

